// data/questions.js
// Complete SSC CGL Master Practice Compendium (200 Questions) + Existing Grammar Banks
// Organized by Subject, Chapter, and Sub-Category / Topic Set.

const pronounQuestions = [
    {"id": 1, "compendiumNo": 1, "subCategory": "Personal Pronouns", "type": "Spot the Error", "prompt": "Siddharth and me are (a)/ planning to shift (b)/ to a new apartment (c)/ next month. (d)", "options": {"a": "(a) Siddharth and me are", "b": "(b) planning to shift", "c": "(c) to a new apartment", "d": "(d) next month."}, "correctOption": "a", "correctedSentence": "Siddharth and I are planning to shift to a new apartment next month.", "rule": "Subjects of a finite verb (are planning) must be in the nominative/subjective case (I, not me).", "distractor": "Part (b) — Students often suspect planning or to shift, overlooking that compound subjects (X and me) hide the objective pronoun me.", "shortcut": "Remove \"Siddharth and\" mentally → \"Me am planning\" sounds wrong → use I."},
    {"id": 2, "compendiumNo": 2, "subCategory": "Personal Pronouns", "type": "Sentence Improvement", "prompt": "The committee distributed the project files among Rohan, Priya, and I.", "options": {"a": "among Rohan, Priya, and me", "b": "among I, Rohan, and Priya", "c": "among Rohan, I, and Priya", "d": "No improvement required"}, "correctOption": "a", "correctedSentence": "among Rohan, Priya, and me", "rule": "Every preposition (among, between, for, to) governs the objective case (me, him, her, us, them).", "distractor": "Option (d) — Aspirants confuse compound objects of prepositions with compound subjects and leave I untouched.", "shortcut": "Spot a preposition (between / among / for) before a list → last pronoun must be me / him / her / us / them."},
    {"id": 3, "compendiumNo": 3, "subCategory": "Personal Pronouns", "type": "Spot the Error", "prompt": "Neither Kavita (a)/ nor her teammates (b)/ can run faster (c)/ than him. (d)", "options": {"a": "(a) Neither Kavita", "b": "(b) nor her teammates", "c": "(c) can run faster", "d": "(d) than him."}, "correctOption": "d", "correctedSentence": "Neither Kavita nor her teammates can run faster than he.", "rule": "In elliptical comparisons using than or as, use the subjective case when comparing subjects (he [can run]).", "distractor": "Part (c) — Test-takers overthink can run faster and miss the case error after than.", "shortcut": "Expand than him to than he [can run] → pick he."},
    {"id": 4, "compendiumNo": 4, "subCategory": "Personal Pronouns", "type": "Spot the Error", "prompt": "It is (a)/ us who have (b)/ funded the entire (c)/ community library. (d)", "options": {"a": "(a) It is", "b": "(b) us who have", "c": "(c) funded the entire", "d": "(d) community library."}, "correctOption": "b", "correctedSentence": "It is we who have funded the entire community library.", "rule": "A pronoun following a form of be (is, am, are, was, were) as a subject complement takes the nominative case (we, not us) in formal SSC grammar.", "distractor": "Part (c) — Students focus on have funded instead of checking the complement pronoun after It is.", "shortcut": "Look for \"It is / was + [pronoun] + who\" → use I / he / she / we / they."},
    {"id": 5, "compendiumNo": 5, "subCategory": "Personal Pronouns", "type": "Spot the Error", "prompt": "It is I who (a)/ is accountable (b)/ for the sudden (c)/ delay in dispatch. (d)", "options": {"a": "(a) It is I who", "b": "(b) is accountable", "c": "(c) for the sudden", "d": "(d) delay in dispatch."}, "correctOption": "b", "correctedSentence": "It is I who am accountable for the sudden delay in dispatch.", "rule": "The verb after a relative pronoun (who, which, that) agrees in person and number with its antecedent (I → am).", "distractor": "Part (a) — Students get distracted by It is I and leave is accountable unchanged.", "shortcut": "Circle the noun/pronoun right before who/which/that (I) → match the verb to it (I am)."},
    {"id": 6, "compendiumNo": 6, "subCategory": "Personal Pronouns", "type": "Spot the Error", "prompt": "You, he, and I (a)/ have been selected (b)/ to represent the college (c)/ No error. (d)", "options": {"a": "(a) You, he, and I", "b": "(b) have been selected", "c": "(c) to represent the college", "d": "(d) No error."}, "correctOption": "d", "correctedSentence": "No error.", "rule": "For positive or neutral actions involving multiple persons, the standard order is 2nd → 3rd → 1st (You, he, and I).", "distractor": "Part (a) — Students who memorize \"2-3-1\" blindly often second-guess even when the sentence already follows \"2-3-1\".", "shortcut": "Positive/neutral sentence? Check 2 - 3 - 1 (you - he/she/they - I/we)."},
    {"id": 7, "compendiumNo": 7, "subCategory": "Personal Pronouns", "type": "Spot the Error", "prompt": "You, Tarun, and I (a)/ must apologize publicly (b)/ for leaking the (c)/ confidential exam schedule. (d)", "options": {"a": "(a) You, Tarun, and I", "b": "(b) must apologize publicly", "c": "(c) for leaking the", "d": "(d) confidential exam schedule."}, "correctOption": "a", "correctedSentence": "Change You, Tarun, and I to I, you, and Tarun.", "rule": "When admitting fault, mistake, or blame, standard SSC grammar uses the 1st → 2nd → 3rd person order.", "distractor": "Part (b) — Students suspect must apologize rather than checking pronoun order for guilt/fault.", "shortcut": "Words like blamed, mess, mistake, apologize (fault) → put I/we first (1 - 2 - 3)."},
    {"id": 8, "compendiumNo": 8, "subCategory": "Personal Pronouns", "type": "Spot the Error", "prompt": "Meena, being a (a)/ diligent analyst, (b)/ she was promoted (c)/ within eight months. (d)", "options": {"a": "(a) Meena, being a", "b": "(b) diligent analyst,", "c": "(c) she was promoted", "d": "(d) within eight months."}, "correctOption": "c", "correctedSentence": "Meena, being a diligent analyst, was promoted within eight months.", "rule": "Do not repeat a subject with both a noun (Meena) and a personal pronoun (she) in the same clause.", "distractor": "Part (a) — Learners fixate on the participial phrase being a diligent analyst and overlook the redundant she.", "shortcut": "Noun + comma + he/she/they/it right before the main verb → delete the extra pronoun."},
    {"id": 9, "compendiumNo": 9, "subCategory": "Personal Pronouns", "type": "Spot the Error", "prompt": "Those students who (a)/ submit their assignments (b)/ late they will (c)/ face a deduction. (d)", "options": {"a": "(a) Those students who", "b": "(b) submit their assignments", "c": "(c) late they will", "d": "(d) face a deduction."}, "correctOption": "c", "correctedSentence": "Those students who submit their assignments late will face a deduction.", "rule": "A relative clause beginning with who already supplies the subject for the main clause; adding they creates a redundant subject.", "distractor": "Part (a) — Students get distracted by Those students who and miss the duplicate subject they.", "shortcut": "Pattern \"Those [noun] who ... [verb], they ...\" → cut they."},
    {"id": 10, "compendiumNo": 10, "subCategory": "Personal Pronouns", "type": "Spot the Error", "prompt": "My father (a)/ objected to (b)/ him staying out (c)/ past midnight. (d)", "options": {"a": "(a) My father", "b": "(b) objected to", "c": "(c) him staying out", "d": "(d) past midnight."}, "correctOption": "c", "correctedSentence": "My father objected to his staying out past midnight.", "rule": "Before a gerund (staying functioning as a noun object of to), formal grammar requires a possessive determiner (his, my, your, their).", "distractor": "Part (b) — Aspirants see objected to and assume him is fine because to is a preposition.", "shortcut": "Preposition + [pronoun] + V-ing (to him staying) → switch pronoun to possessive (his/my/their). Set 2: Possessive Pronouns, Determiners & Comparisons (Q11–Q20)"},
    {"id": 11, "compendiumNo": 11, "subCategory": "Possessive Pronouns", "type": "Spot the Error", "prompt": "This notebook is (a)/ not ours; it (b)/ must be (c)/ her's. (d)", "options": {"a": "(a) This notebook is", "b": "(b) not ours; it", "c": "(c) must be", "d": "(d) her's."}, "correctOption": "d", "correctedSentence": "Change her's to hers.", "rule": "Possessive pronouns (hers, yours, theirs, ours, mine, its) never take an apostrophe.", "distractor": "Part (b) — Students misread ours as an error because our is the determiner, even though ours is already correct.", "shortcut": "Spot his' / her's / your's / their's / it's (as possessive) → remove the apostrophe."},
    {"id": 12, "compendiumNo": 12, "subCategory": "Possessive Pronouns", "type": "Spot the Error", "prompt": "The startup plans to (a)/ expand their operations (b)/ across tier-two cities (c)/ before next winter. (d)", "options": {"a": "(a) The startup plans to", "b": "(b) expand their operations", "c": "(c) across tier-two cities", "d": "(d) before next winter."}, "correctOption": "b", "correctedSentence": "Change their to its.", "rule": "Singular corporate entities like the startup or the company acting as a single unit take the singular possessive its.", "distractor": "Part (c) — Test-takers get distracted by the plural noun tier-two cities and think their matches cities.", "shortcut": "Singular organization (company / bank / startup / committee) + their → change to its."},
    {"id": 13, "compendiumNo": 13, "subCategory": "Possessive Pronouns", "type": "Spot the Error", "prompt": "The municipality announced (a)/ that it would (b)/ revise its property (c)/ No error. (d)", "options": {"a": "(a) The municipality announced", "b": "(b) that it would", "c": "(c) revise its property", "d": "(d) No error."}, "correctOption": "d", "correctedSentence": "No error.", "rule": "Singular institutional nouns (the municipality) consistently pair with singular pronouns (it, its) when viewed as a single administrative body.", "distractor": "Part (b) — Students often doubt it would revise when the subject is an institutional noun.", "shortcut": "Check if the subject is singular and the pronoun already matches (municipality → it / its) → No error."},
    {"id": 14, "compendiumNo": 14, "subCategory": "Possessive Pronouns", "type": "Spot the Error", "prompt": "Your apartment in (a)/ Pune is much (b)/ more spacious than (c)/ my one in Mumbai. (d)", "options": {"a": "(a) Your apartment in", "b": "(b) Pune is much", "c": "(c) more spacious than", "d": "(d) my one in Mumbai."}, "correctOption": "d", "correctedSentence": "Change my one to mine.", "rule": "Use the possessive pronoun mine (not my one) to stand in for my apartment in comparisons.", "distractor": "Part (c) — Students focus on more spacious and miss my one.", "shortcut": "See my one / your one / her one in a comparison → replace with mine / yours / hers."},
    {"id": 15, "compendiumNo": 15, "subCategory": "Possessive Pronouns", "type": "Spot the Error", "prompt": "Is that vintage (a)/ wristwatch in the (b)/ showcase really (c)/ your? (d)", "options": {"a": "(a) Is that vintage", "b": "(b) wristwatch in the", "c": "(c) showcase really", "d": "(d) your?"}, "correctOption": "d", "correctedSentence": "Change your to yours.", "rule": "At the end of a clause without a following noun, use the possessive pronoun (yours), not the possessive determiner (your).", "distractor": "Part (a) — Students get tripped up by that vintage wristwatch and overlook your at the end.", "shortcut": "Your / my / her / their sitting alone at the end of a sentence → add -s (yours / hers / theirs or mine)."},
    {"id": 16, "compendiumNo": 16, "subCategory": "Possessive Pronouns", "type": "Spot the Error", "prompt": "With grain silos (a)/ brimming, the state (b)/ government wants to (c)/ offload his excess stock. (d)", "options": {"a": "(a) With grain silos", "b": "(b) brimming, the state", "c": "(c) government wants to", "d": "(d) offload his excess stock."}, "correctOption": "d", "correctedSentence": "Change his to its.", "rule": "Non-human/institutional subjects like the state government take its (or their when treated as multiple bodies), never his.", "distractor": "Part (b) — Learners focus on brimming without checking the gender/animacy of his.", "shortcut": "Government/institution + his/her → change to its (or their if plural)."},
    {"id": 17, "compendiumNo": 17, "subCategory": "Possessive Pronouns", "type": "Spot the Error", "prompt": "Both of mine (a)/ younger brothers have (b)/ cleared the civil (c)/ services prelims. (d)", "options": {"a": "(a) Both of mine", "b": "(b) younger brothers have", "c": "(c) cleared the civil", "d": "(d) services prelims."}, "correctOption": "a", "correctedSentence": "Change mine to my.", "rule": "Before a noun (younger brothers), use the possessive determiner (my), not the independent pronoun mine.", "distractor": "Part (b) — Students check have cleared and ignore mine before a noun.", "shortcut": "Mine + [noun] (mine brother/book) → swap to my + [noun]."},
    {"id": 18, "compendiumNo": 18, "subCategory": "Possessive Pronouns", "type": "Spot the Error", "prompt": "The data published in (a)/ this annual report (b)/ is far more reliable (c)/ than that report. (d)", "options": {"a": "(a) The data published in", "b": "(b) this annual report", "c": "(c) is far more reliable", "d": "(d) than that report."}, "correctOption": "d", "correctedSentence": "Change that report to that in that report.", "rule": "Comparisons must be between like elements (the data vs. the data in that report), not data and a report.", "distractor": "Part (a) — Students get caught up in data ... is and miss the faulty comparison at the end.", "shortcut": "Comparing X with that/those + [noun]? Add of/in + that/those + [noun] so apples match apples."},
    {"id": 19, "compendiumNo": 19, "subCategory": "Possessive Pronouns", "type": "Spot the Error", "prompt": "The lectures delivered (a)/ in this workshop (b)/ are more practical (c)/ than other workshops. (d)", "options": {"a": "(a) The lectures delivered", "b": "(b) in this workshop", "c": "(c) are more practical", "d": "(d) than other workshops."}, "correctOption": "d", "correctedSentence": "Change other workshops to those in other workshops.", "rule": "The lectures is being compared with lectures from other workshops, requiring those.", "distractor": "Part (c) — Test-takers check more practical and overlook the missing comparative pronoun those.", "shortcut": "Plural subject (lectures) compared with another group without those → insert those in/of."},
    {"id": 20, "compendiumNo": 20, "subCategory": "Possessive Pronouns", "type": "Spot the Error", "prompt": "His separation (a)/ caused deep distress (b)/ among all members (c)/ of the household. (d)", "options": {"a": "(a) His separation", "b": "(b) caused deep distress", "c": "(c) among all members", "d": "(d) of the household."}, "correctOption": "a", "correctedSentence": "Change His separation to Separation from him.", "rule": "In strict SSC convention, nouns like separation, favour, and leave avoid a possessive determiner when meaning \"being apart from someone\".", "distractor": "Part (c) — Students look at among all members and miss the possessive idiom error in (a).", "shortcut": "Watch for [possessive] + separation/favour in SSC error lists → change to separation from / favour from. Set 3: Reflexive & Emphatic Pronouns (Q21–Q30)"},
    {"id": 21, "compendiumNo": 21, "subCategory": "Reflexive & Emphatic", "type": "Spot the Error", "prompt": "I had to grip (a)/ the railing tightly (b)/ to balance itself (c)/ on the wet stairs. (d)", "options": {"a": "(a) I had to grip", "b": "(b) the railing tightly", "c": "(c) to balance itself", "d": "(d) on the wet stairs."}, "correctOption": "c", "correctedSentence": "Change itself to myself.", "rule": "A reflexive pronoun must match the subject (I → myself), not a non-human noun like railing.", "distractor": "Part (a) — Aspirants focus on grip ... tightly and miss the mismatched reflexive itself.", "shortcut": "Subject is I → reflexive must be myself (never itself)."},
    {"id": 22, "compendiumNo": 22, "subCategory": "Reflexive & Emphatic", "type": "Spot the Error", "prompt": "The candidates should (a)/ avail of every (b)/ mock test before (c)/ the final exam. (d)", "options": {"a": "(a) The candidates should", "b": "(b) avail of every", "c": "(c) mock test before", "d": "(d) the final exam."}, "correctOption": "b", "correctedSentence": "Change avail of to avail themselves of.", "rule": "When meaning \"take advantage of,\" avail requires a reflexive pronoun + of (avail oneself of).", "distractor": "Part (d) — Students treat avail of as a fixed phrasal verb without noticing the missing reflexive object.", "shortcut": "Spot avail + of with no reflexive → insert the matching -self/-selves pronoun."},
    {"id": 23, "compendiumNo": 23, "subCategory": "Reflexive & Emphatic", "type": "Spot the Error", "prompt": "You must exert (a)/ to complete the (b)/ syllabus well ahead (c)/ of the deadline. (d)", "options": {"a": "(a) You must exert", "b": "(b) to complete the", "c": "(c) syllabus well ahead", "d": "(d) of the deadline."}, "correctOption": "a", "correctedSentence": "Change exert to exert yourself.", "rule": "In standard SSC grammar, exert (meaning \"make a strong effort\") takes a reflexive object (exert oneself) when no other object is given.", "distractor": "Part (b) — Test-takers focus on to complete and overlook the missing reflexive after exert.", "shortcut": "Verb exert with no direct object → add oneself / yourself / themselves."},
    {"id": 24, "compendiumNo": 24, "subCategory": "Reflexive & Emphatic", "type": "Spot the Error", "prompt": "He prostrated (a)/ before the judge (b)/ pleading for mercy (c)/ after the verdict. (d)", "options": {"a": "(a) He prostrated", "b": "(b) before the judge", "c": "(c) pleading for mercy", "d": "(d) after the verdict."}, "correctOption": "a", "correctedSentence": "Change prostrated to prostrated himself.", "rule": "Prostrate (lying stretched out in submission/supplication) requires a reflexive object (prostrate oneself).", "distractor": "Part (c) — Students get drawn to pleading for mercy and miss prostrated.", "shortcut": "Verb prostrate followed directly by a preposition (before/at) → insert himself / herself / myself / themselves."},
    {"id": 25, "compendiumNo": 25, "subCategory": "Reflexive & Emphatic", "type": "Spot the Error", "prompt": "We should do (a)/ brisk walking daily (b)/ to keep (c)/ ourselves energized. (d)", "options": {"a": "(a) We should do", "b": "(b) brisk walking daily", "c": "(c) to keep", "d": "(d) ourselves energized."}, "correctOption": "d", "correctedSentence": "Remove ourselves.", "rule": "Verbs like keep, stop, turn, qualify, and bathe do not take reflexive pronouns in standard SSC grammar.", "distractor": "Part (b) — Many students suspect brisk walking and leave ourselves untouched.", "shortcut": "Keep / stop / bathe + myself/ourselves/himself → drop the reflexive."},
    {"id": 26, "compendiumNo": 26, "subCategory": "Reflexive & Emphatic", "type": "Spot the Error", "prompt": "He bathed (a)/ himself in the (b)/ cold river at (c)/ dawn every day. (d)", "options": {"a": "(a) He bathed", "b": "(b) himself in the", "c": "(c) cold river at", "d": "(d) dawn every day."}, "correctOption": "b", "correctedSentence": "He bathed in the cold river at dawn every day.", "rule": "In SSC grammar, bathe (like dress, shave, hide) does not take a reflexive pronoun in routine action sentences.", "distractor": "Part (c) — Test-takers focus on at dawn or in the cold river and accept bathed himself as natural.", "shortcut": "Bathed himself / dressed herself in plain daily actions → cut the reflexive."},
    {"id": 27, "compendiumNo": 27, "subCategory": "Reflexive & Emphatic", "type": "Spot the Error", "prompt": "Myself and Aarav (a)/ will coordinate the (b)/ logistics for the (c)/ seminar tomorrow. (d)", "options": {"a": "(a) Myself and Aarav", "b": "(b) will coordinate the", "c": "(c) logistics for the", "d": "(d) seminar tomorrow."}, "correctOption": "a", "correctedSentence": "Change Myself and Aarav to Aarav and I.", "rule": "Reflexive pronouns (myself, himself) cannot act as the subject of a sentence.", "distractor": "Part (c) — Students focus on coordinate the logistics and ignore Myself in the subject slot.", "shortcut": "Myself / himself / herself as the subject of a verb → replace with I / he / she."},
    {"id": 28, "compendiumNo": 28, "subCategory": "Reflexive & Emphatic", "type": "Spot the Error", "prompt": "One should always (a)/ stand by his (b)/ principles even under (c)/ severe pressure. (d)", "options": {"a": "(a) One should always", "b": "(b) stand by his", "c": "(c) principles even under", "d": "(d) severe pressure."}, "correctOption": "b", "correctedSentence": "Change his to one's.", "rule": "When the indefinite pronoun one is the subject, its corresponding possessive determiner is one's (and reflexive is oneself).", "distractor": "Part (a) — Test-takers focus on stand by and overlook his referring back to one.", "shortcut": "Subject is One → look for one's (not his/her/their)."},
    {"id": 29, "compendiumNo": 29, "subCategory": "Reflexive & Emphatic", "type": "Spot the Error", "prompt": "Now it has (a)/ finally dawned upon (b)/ him that one (c)/ must guard one's privacy. (d)", "options": {"a": "(a) Now it has", "b": "(b) finally dawned upon", "c": "(c) him that one", "d": "(d) must guard one's privacy."}, "correctOption": "d", "correctedSentence": "No error.", "rule": "The second clause introduces a new subject one, which properly takes one's (and does not need to match him in the earlier clause).", "distractor": "Part (b) — Students get confused by dawned upon him and try to change one's to his.", "shortcut": "One ... one's together in the same clause → No error."},
    {"id": 30, "compendiumNo": 30, "subCategory": "Reflexive & Emphatic", "type": "Spot the Error", "prompt": "We must watch (a)/ our diet carefully (b)/ in order to (c)/ keep oneself fit. (d)", "options": {"a": "(a) We must watch", "b": "(b) our diet carefully", "c": "(c) in order to", "d": "(d) keep oneself fit."}, "correctOption": "d", "correctedSentence": "Change oneself to ourselves.", "rule": "The subject of the sentence is We, so the matching reflexive/referent is ourselves, not the generic oneself.", "distractor": "Part (a) — Test-takers look at watch our diet and miss the shift to oneself at the end.", "shortcut": "Subject We with oneself → match to ourselves. Set 4: Relative, Interrogative & Demonstrative Pronouns (Q31–Q40)"},
    {"id": 31, "compendiumNo": 31, "subCategory": "Relative & Interrogative", "type": "Spot the Error", "prompt": "That is the (a)/ engineer whom I (b)/ believe designed the (c)/ suspension bridge. (d)", "options": {"a": "(a) That is the", "b": "(b) engineer whom I", "c": "(c) believe designed the", "d": "(d) suspension bridge."}, "correctOption": "b", "correctedSentence": "Change whom to who.", "rule": "Who is the subject of designed, even though I believe is parenthetically inserted between who and designed.", "distractor": "Part (c) — Students see I believe right after whom and assume whom is an object of believe.", "shortcut": "Spot who/whom + [I think/believe/know] + [verb] → delete I think/believe mentally: if a subject is missing before the verb, pick who."},
    {"id": 32, "compendiumNo": 32, "subCategory": "Relative & Interrogative", "type": "Spot the Error", "prompt": "I met the (a)/ intern whose father (b)/ retired as a (c)/ No error. (d)", "options": {"a": "(a) I met the", "b": "(b) intern whose father", "c": "(c) retired as a", "d": "(d) No error."}, "correctOption": "d", "correctedSentence": "No error.", "rule": "Whose expresses possession (the intern's father) and modifies animate antecedents naturally.", "distractor": "Part (b) — Students sometimes confuse whose with who's (who is) and mark (b) as an error.", "shortcut": "Whose + [noun] (whose father) = possession → No error if who is isn't meant."},
    {"id": 33, "compendiumNo": 33, "subCategory": "Relative & Interrogative", "type": "Spot the Error", "prompt": "This is the (a)/ old auditorium, of (b)/ who the roof (c)/ collapsed last week. (d)", "options": {"a": "(a) This is the", "b": "(b) old auditorium, of", "c": "(c) who the roof", "d": "(d) collapsed last week."}, "correctOption": "c", "correctedSentence": "Change of who to of which (or whose roof).", "rule": "For non-human/inanimate antecedents (auditorium), use which, never who.", "distractor": "Part (d) — Aspirants focus on collapsed last week and miss of who.", "shortcut": "Non-living thing + who/whom → switch to which (or whose + noun)."},
    {"id": 34, "compendiumNo": 34, "subCategory": "Relative & Interrogative", "type": "Spot the Error", "prompt": "He is one (a)/ of the sharpest (b)/ analysts who has (c)/ worked in this firm. (d)", "options": {"a": "(a) He is one", "b": "(b) of the sharpest", "c": "(c) analysts who has", "d": "(d) worked in this firm."}, "correctOption": "c", "correctedSentence": "Change who has to who have.", "rule": "In one of the + [plural noun] + who/which/that, the relative pronoun's antecedent is the plural noun (analysts), taking a plural verb (have).", "distractor": "Part (a) — Students spot one of and automatically apply a singular verb has, forgetting the plural antecedent analysts.", "shortcut": "One of the [plural nouns] + who + [verb] → make the verb plural (unless restricted by the only one)."},
    {"id": 35, "compendiumNo": 35, "subCategory": "Relative & Interrogative", "type": "Spot the Error", "prompt": "She is the (a)/ only candidate who (b)/ have cleared all (c)/ three stages. (d)", "options": {"a": "(a) She is the", "b": "(b) only candidate who", "c": "(c) have cleared all", "d": "(d) three stages."}, "correctOption": "c", "correctedSentence": "Change who have to who has.", "rule": "When modified by the only (the only candidate), the relative pronoun who refers to the singular candidate, requiring has.", "distractor": "Part (d) — Test-takers check all three stages and overlook who have.", "shortcut": "The only [singular noun] + who + [verb] → use a singular verb (has/is/was)."},
    {"id": 36, "compendiumNo": 36, "subCategory": "Relative & Interrogative", "type": "Spot the Error", "prompt": "He was unaware of (a)/ the rules and the (b)/ people who had (c)/ framed the policy. (d)", "options": {"a": "(a) He was unaware of", "b": "(b) the rules and the", "c": "(c) people who had", "d": "(d) framed the policy."}, "correctOption": "c", "correctedSentence": "Change who to that.", "rule": "When a relative pronoun refers jointly to a thing/concept (rules) and a person (people), that is used instead of who or which.", "distractor": "Part (a) — Students focus on unaware of and miss the mixed antecedent.", "shortcut": "Mixed antecedent (thing + person) → pick that."},
    {"id": 37, "compendiumNo": 37, "subCategory": "Relative & Interrogative", "type": "Spot the Error", "prompt": "It is the (a)/ most inspiring novel (b)/ which I have (c)/ read this year. (d)", "options": {"a": "(a) It is the", "b": "(b) most inspiring novel", "c": "(c) which I have", "d": "(d) read this year."}, "correctOption": "c", "correctedSentence": "Change which to that.", "rule": "After a superlative adjective (the most inspiring), that is preferred over which.", "distractor": "Part (b) — Learners check most inspiring and accept which for a book.", "shortcut": "Superlative (most/best/only/all) + which → swap to that."},
    {"id": 38, "compendiumNo": 38, "subCategory": "Relative & Interrogative", "type": "Spot the Error", "prompt": "You can pick (a)/ that you like (b)/ from the display (c)/ counter today. (d)", "options": {"a": "(a) You can pick", "b": "(b) that you like", "c": "(c) from the display", "d": "(d) counter today."}, "correctOption": "b", "correctedSentence": "Change that to what (or whatever).", "rule": "Without a preceding antecedent noun, what/whatever acts as a fused relative pronoun (the thing(s) that).", "distractor": "Part (c) — Students focus on display counter and miss the missing antecedent before that.", "shortcut": "Verb + that you want/like with no noun before that → change that to what / whatever."},
    {"id": 39, "compendiumNo": 39, "subCategory": "Relative & Interrogative", "type": "Spot the Error", "prompt": "There are two (a)/ candidates here, (b)/ but who of them (c)/ is more suitable? (d)", "options": {"a": "(a) There are two", "b": "(b) candidates here,", "c": "(c) but who of them", "d": "(d) is more suitable?"}, "correctOption": "c", "correctedSentence": "Change who to which.", "rule": "When selecting one out of a specific, limited group (two candidates, of them), which is used instead of who.", "distractor": "Part (d) — Aspirants focus on is more suitable and overlook who of them.", "shortcut": "Which of + [group/them/us] → always which (even for people)."},
    {"id": 40, "compendiumNo": 40, "subCategory": "Relative & Interrogative", "type": "Spot the Error", "prompt": "To who did (a)/ you hand over (b)/ the sealed envelope (c)/ this morning? (d)", "options": {"a": "(a) To who did", "b": "(b) you hand over", "c": "(c) the sealed envelope", "d": "(d) this morning?"}, "correctOption": "a", "correctedSentence": "Change who to whom.", "rule": "Following a preposition (To) and functioning as the indirect object of hand over, the objective form whom is required.", "distractor": "Part (b) — Students focus on hand over and leave who unchanged.", "shortcut": "Preposition + who (to who / for who / with who) → change to whom. Set 5: Distributive, Indefinite & Reciprocal Pronouns (Q41–Q50)"},
    {"id": 41, "compendiumNo": 41, "subCategory": "Distributive & Indefinite", "type": "Spot the Error", "prompt": "Neither of the (a)/ two applicants have (b)/ submitted the required (c)/ domicile certificate. (d)", "options": {"a": "(a) Neither of the", "b": "(b) two applicants have", "c": "(c) submitted the required", "d": "(d) domicile certificate."}, "correctOption": "b", "correctedSentence": "Change have to has.", "rule": "Neither of (like either of and each of) followed by a plural noun takes a singular verb (has) in formal grammar.", "distractor": "Part (a) — Test-takers see two applicants (plural) and match have to applicants instead of Neither.", "shortcut": "Neither / Either / Each of + [plural] → singular verb (has / is / was)."},
    {"id": 42, "compendiumNo": 42, "subCategory": "Distributive & Indefinite", "type": "Spot the Error", "prompt": "Any of the (a)/ two routes leading (b)/ to the hill station (c)/ is blocked by landslides. (d)", "options": {"a": "(a) Any of the", "b": "(b) two routes leading", "c": "(c) to the hill station", "d": "(d) is blocked by landslides."}, "correctOption": "a", "correctedSentence": "Change Any to Either.", "rule": "Either refers to one of two items, whereas any is used for more than two.", "distractor": "Part (d) — Students check is blocked and miss Any used for two routes.", "shortcut": "Two items/routes/options → use either / neither / both, never any / none."},
    {"id": 43, "compendiumNo": 43, "subCategory": "Distributive & Indefinite", "type": "Spot the Error", "prompt": "I asked three (a)/ passersby for directions, (b)/ but neither of them (c)/ knew the way. (d)", "options": {"a": "(a) I asked three", "b": "(b) passersby for directions,", "c": "(c) but neither of them", "d": "(d) knew the way."}, "correctOption": "c", "correctedSentence": "Change neither to none.", "rule": "None refers to more than two (here three passersby), whereas neither applies strictly to two.", "distractor": "Part (d) — Students focus on knew the way and overlook neither for three people.", "shortcut": "More than two + negative choice → use none (not neither)."},
    {"id": 44, "compendiumNo": 44, "subCategory": "Distributive & Indefinite", "type": "Spot the Error", "prompt": "None of the (a)/ candidates deserves (b)/ to be disqualified (c)/ No error. (d)", "options": {"a": "(a) None of the", "b": "(b) candidates deserves", "c": "(c) to be disqualified", "d": "(d) No error."}, "correctOption": "d", "correctedSentence": "No error.", "rule": "None of followed by a plural noun (candidates) takes a singular verb (deserves) in standard SSC grammar.", "distractor": "Part (b) — Students who believe none is always plural try to change deserves to deserve.", "shortcut": "None of + [plural noun] in SSC grammar → singular verb (deserves / is / was) is standard."},
    {"id": 45, "compendiumNo": 45, "subCategory": "Distributive & Indefinite", "type": "Spot the Error", "prompt": "Each of the (a)/ volunteers must carry (b)/ their identity card (c)/ during the drive. (d)", "options": {"a": "(a) Each of the", "b": "(b) volunteers must carry", "c": "(c) their identity card", "d": "(d) during the drive."}, "correctOption": "c", "correctedSentence": "Change their to his (or his or her).", "rule": "Each is grammatically singular, so in traditional SSC rules it takes a singular possessive determiner, not their.", "distractor": "Part (b) — Aspirants focus on must carry and miss their.", "shortcut": "Each of + [plural] → singular verb and singular possessive (his / his or her)."},
    {"id": 46, "compendiumNo": 46, "subCategory": "Distributive & Indefinite", "type": "Spot the Error", "prompt": "The three teammates (a)/ blamed each other (b)/ for missing the (c)/ final penalty kick. (d)", "options": {"a": "(a) The three teammates", "b": "(b) blamed each other", "c": "(c) for missing the", "d": "(d) final penalty kick."}, "correctOption": "b", "correctedSentence": "Change each other to one another.", "rule": "In traditional SSC grammar rules, each other is used for two, while one another is used for more than two (three teammates).", "distractor": "Part (c) — Students focus on missing the final penalty kick and overlook each other for three people.", "shortcut": "Two → each other; Three or more → one another."},
    {"id": 47, "compendiumNo": 47, "subCategory": "Distributive & Indefinite", "type": "Spot the Error", "prompt": "Both of the (a)/ finalists are not (b)/ eligible for the (c)/ junior category prize. (d)", "options": {"a": "(a) Both of the", "b": "(b) finalists are not", "c": "(c) eligible for the", "d": "(d) junior category prize."}, "correctOption": "b", "correctedSentence": "Change Both of the finalists are not to Neither of the finalists is.", "rule": "Standard SSC grammar avoids both ... not in negative sentences, using neither + singular verb instead.", "distractor": "Part (c) — Test-takers check eligible for and miss Both ... not.", "shortcut": "Both ... not → replace with Neither ... [singular verb]."},
    {"id": 48, "compendiumNo": 48, "subCategory": "Distributive & Indefinite", "type": "Spot the Error", "prompt": "Many a student (a)/ have struggled with (b)/ time management in (c)/ the quantitative section. (d)", "options": {"a": "(a) Many a student", "b": "(b) have struggled with", "c": "(c) time management in", "d": "(d) the quantitative section."}, "correctOption": "b", "correctedSentence": "Change have to has.", "rule": "The structure Many a + singular noun (Many a student) is singular in form and takes a singular verb (has).", "distractor": "Part (a) — Students see Many at the start and assume a plural verb have is needed.", "shortcut": "Many a + [singular noun] → treat as singular (has / is / was)."},
    {"id": 49, "compendiumNo": 49, "subCategory": "Distributive & Indefinite", "type": "Spot the Error", "prompt": "There is many (a)/ reasons why commuters (b)/ prefer the metro (c)/ during peak hours. (d)", "options": {"a": "(a) There is many", "b": "(b) reasons why commuters", "c": "(c) prefer the metro", "d": "(d) during peak hours."}, "correctOption": "a", "correctedSentence": "Change is to are.", "rule": "In existential there sentences, the verb agrees with the real subject that follows it (many reasons is plural → are).", "distractor": "Part (c) — Learners focus on prefer the metro and overlook There is before a plural noun.", "shortcut": "There is/are + [noun] → flip it mentally: \"Many reasons are...\" → pick are."},
    {"id": 50, "compendiumNo": 50, "subCategory": "Distributive & Indefinite", "type": "Spot the Error", "prompt": "There was a (a)/ sudden power cut (b)/ in the auditorium (c)/ No error. (d)", "options": {"a": "(a) There was a", "b": "(b) sudden power cut", "c": "(c) in the auditorium", "d": "(d) No error."}, "correctOption": "d", "correctedSentence": "No error.", "rule": "There was properly agrees with the singular noun phrase a sudden power cut.", "distractor": "Part (b) — Students overthink power cut (compound noun) and mark (b) when the sentence is grammatically sound.", "shortcut": "Singular noun after There was → No error. Part II: Indian History — NCERT Class VI–XII (50 Questions) Chapter 1: Harappan Civilisation & Vedic Age — NCERT Class VI & XII Theme 1 (Q51– Q60)"}
];

